it("RB-18: detects when a module-level function still carries a docblock", () => {
  const source = [
    "// Docs: ./graph-runtime.md",
    "export const run = (): void => {};",
    "",
  ].join("\n");
  const withDoc = [
    "// Docs: ./graph-runtime.md",
    "/** Why. */",
    "export const run = (): void => {};",
    "",
  ].join("\n");
  expect(docblocked(source)).toEqual([]);
  expect(docblocked(withDoc)).toEqual(["run"]);
});

